library(haven)
library(dplyr)
library(tidyr)
library(purrr)
library(labelled)
library(readr)

# Load datasets
wave1 <- read_delim("data/input/wave_one_lsype_family_background_2020.tab", delim = "\t", show_col_types = FALSE)
wave2 <- read_delim("data/input/wave_two_lsype_family_background_2020.tab", delim = "\t", show_col_types = FALSE)
wave4 <- read_delim("data/input/wave_four_lsype_family_background_2020.tab", delim = "\t", show_col_types = FALSE)

# Merge datasets using full_join by NSID
merged_data <- wave1 %>%
  full_join(wave2, by = "NSID") %>%
  full_join(wave4, by = "NSID")

# Define a function to harmonize missing values
harmonize_missing <- function(x) {
  case_when(
    x %in% c(-999, -998, -997, -995) ~ -2,  # Schedule not applicable / script error / information lost
    x == -94 ~ -8,                           # Insufficient information
    x == -92 ~ -9,                           # Refused
    x == -91 ~ -1,                           # Not applicable
    x == -99 ~ -3,                           # Not asked at the fieldwork stage / not interviewed
    x == -100 ~ -3,                          # Not asked at the fieldwork stage / not interviewed
    x == -97 ~ -3,                           # Not asked at the fieldwork stage / not interviewed
    x == -1 ~ -7,                            # Prefer not to say
    TRUE ~ x
  )
}

# Apply harmonization to each wave's variables
for (var in c("W1hiqualmum", "W1hiqualdad", "W2hiqualmum", "W2hiqualdad", "w4hiqualmum", "w4hiqualdad")) {
  merged_data[[var]] <- harmonize_missing(merged_data[[var]])
}

# Define a function to derive consolidated education variables
derive_consolidated_educ <- function(merged_data, waves, suffix) {
  # Initialize result variable with -3 (not asked)
  result <- rep(-3, nrow(merged_data))

  # Iterate through waves in order
  for (wave in waves) {
    # Determine the current wave's variable
    if (suffix == "ma") {
      if (wave == "W1") {
        current_var <- "W1hiqualmum"
      } else if (wave == "W2") {
        current_var <- "W2hiqualmum"
      } else if (wave == "W4") {
        current_var <- "w4hiqualmum"
      }
    } else if (suffix == "pa") {
      if (wave == "W1") {
        current_var <- "W1hiqualdad"
      } else if (wave == "W2") {
        current_var <- "W2hiqualdad"
      } else if (wave == "W4") {
        current_var <- "w4hiqualdad"
      }
    }

    # Check for positive values (1-20) where result is still -3
    positive_indices <- which(merged_data[[current_var]] > 0 & merged_data[[current_var]] <= 20 & result == -3)
    if (length(positive_indices) > 0) {
      result[positive_indices] <- merged_data[[current_var]][positive_indices]
    }
  }

  # If no positive values found, assign the first negative code in wave order
  for (wave in waves) {
    if (suffix == "ma") {
      if (wave == "W1") {
        current_var <- "W1hiqualmum"
      } else if (wave == "W2") {
        current_var <- "W2hiqualmum"
      } else if (wave == "W4") {
        current_var <- "w4hiqualmum"
      }
    } else if (suffix == "pa") {
      if (wave == "W1") {
        current_var <- "W1hiqualdad"
      } else if (wave == "W2") {
        current_var <- "W2hiqualdad"
      } else if (wave == "W4") {
        current_var <- "w4hiqualdad"
      }
    }

    # Check for negative codes where result is still -3
    negative_indices <- which(merged_data[[current_var]] < 0 & result == -3)
    if (length(negative_indices) > 0) {
      result[negative_indices] <- merged_data[[current_var]][negative_indices]
    }
  }

  return(result)
}

# Derive detailed consolidated variables
merged_data$educdtlma <- derive_consolidated_educ(merged_data, c("W1", "W2", "W4"), "ma")
merged_data$educdtlpa <- derive_consolidated_educ(merged_data, c("W1", "W2", "W4"), "pa")

# Define the mapping for the collapsed NVQ scheme
nvq_mapping <- c(
  "1" = 0, "2" = 0, "3" = 0, "4" = 0,  # NVQ 4–5
  "5" = 1, "6" = 1, "7" = 1, "8" = 1, "9" = 1, "10" = 1, "11" = 1, "12" = 1, "13" = 1, "14" = 1,  # NVQ 1–3
  "15" = 1, "16" = 1, "17" = 1,  # NVQ 1–3
  "18" = 2,  # Youth training / skill seekers
  "19" = 3,  # Qualification, level unspecified
  "20" = 4   # No qualification mentioned
)

# Derive collapsed NVQ variables
merged_data$educma <- recode(as.character(merged_data$educdtlma), !!!nvq_mapping, .default = -3)
merged_data$educpa <- recode(as.character(merged_data$educdtlpa), !!!nvq_mapping, .default = -3)

# Select only the required variables for output
output_data <- merged_data %>%
  select(NSID, educdtlma, educdtlpa, educma, educpa)

# Write the output CSV
write_csv(output_data, "data/output/cleaned_data.csv")

# Return the path to the output file
"data/output/cleaned_data.csv"

